fn solve(n: i8, k: i8) -> Vec<i8> {
    // Number of unselected items
    let unselected = n - k;

    // Determine the bounds [x_min, x_max]
    let (x_min, x_max) = if k == 0 || k == n {
        // If no items are selected or all items are selected,
        // there can be no "good" unselected items.
        (0, 0)
    } else {
        // Otherwise there's at least one selected and one unselected
        let x_min = 1;
        // Compute twice the selected count safely (saturating on overflow).
        // Then take the min with the number of unselected items.
        let two_k = k.saturating_mul(2);
        let x_max = std::cmp::min(unselected, two_k);
        (x_min, x_max)
    };

    vec![x_min, x_max]
}

